// recipe: virtual-key-stats
// args: none
// serves: cross-player-eat-skips-native-steps (the ring's own key never flipped, and the two causes look identical from one frame)
// returns: ok, staged, keyQueries, keyDownAnswers, frame, error, detail
//
// What the acceptance channel's virtual KEYBOARD has seen: how many KEY questions the game asked for a staged key, how many of those were answered
// "down", how many keys a batch still stages, and the frame this read happened in. A press that never reached the game and a press the game read while
// the branch did nothing produce the same one-frame picture; this census tells them apart.
((System.Func<string>)(() => { var findType = new System.Func<string, System.Type>((simpleName) => { var assemblies = System.AppDomain.CurrentDomain.GetAssemblies(); for (var i = 0; i < assemblies.Length; i++) { System.Type[] types; try { types = assemblies[i].GetTypes(); } catch { continue; } for (var t = 0; t < types.Length; t++) { if (types[t].Name == simpleName) { return types[t]; } } } return null; }); var vi = findType("VirtualInput"); if (vi == null) { return "{\"ok\":false,\"error\":\"no-VirtualInput\"}"; } const System.Reflection.BindingFlags F = System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic; var staged = (int)vi.GetProperty("StagedKeyCount", F).GetValue(null, null); var queries = (int)vi.GetProperty("KeyQueries", F).GetValue(null, null); var downs = (int)vi.GetProperty("KeyDownAnswers", F).GetValue(null, null); System.Type timeType = null; var asms = System.AppDomain.CurrentDomain.GetAssemblies(); for (var i = 0; i < asms.Length && timeType == null; i++) { timeType = asms[i].GetType("UnityEngine.Time"); } var frame = timeType == null ? -1 : (int)timeType.GetProperty("frameCount").GetValue(null, null); return "{\"ok\":true,\"staged\":" + staged + ",\"keyQueries\":" + queries + ",\"keyDownAnswers\":" + downs + ",\"frame\":" + frame + "}"; }))()
